  const rowsHtml = endpoints.map((ep) => `<tr><td><span class="method-badge method-${ep.method.toLowerCase()}">${ep.method}</span></td><td>${escapeHtml(ep.path)}</td><td>${escapeHtml(ep.summary)}</td></tr>`).join("");
  return `<table class="preview-table"><thead><tr><th>메서드</th><th>경로</th><th>요약</th></tr></thead><tbody>${rowsHtml}</tbody></table>`;
